    static char findNthDigit(int n) {
        StringBuilder sb = new StringBuilder();
        int num = 1;
        while (sb.length() < n) {
            sb.append(num);                   // append this number's digits one at a time
            num++;
        }
        return sb.charAt(n - 1);
    }
}

