public class Main {
    static char findNthDigit(int n) {
        int digits = 1;
        long count = 9, start = 1;
        while (n > digits * count) {                 // skip this whole digit-length group
            n -= digits * count;
            digits++;
            count *= 10;
            start *= 10;
        }
        long num = start + (n - 1) / digits;             // the specific number containing the target digit
        int idx = (n - 1) % digits;                        // the specific digit within that number
        return String.valueOf(num).charAt(idx);
    }
}

